<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Hyper3D Rodin Clone</title>
    <style>
        :root {
            --bg-dark: #0f0f12;
            --card-bg: #1a1a20;
            --text-primary: #ffffff;
            --text-secondary: #a0a0b0;
            --accent-purple: #6d28d9;
            --border-color: #2e2e38;
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            --font-mono: "Courier New", Courier, monospace;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-dark);
            color: var(--text-primary);
            font-family: var(--font-sans);
            height: 100vh;
            width: 100vw;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            position: relative;
            /* Simulating the background gradient/blur */
            background-image: radial-gradient(circle at 50% 40%, #2a2025 0%, #121215 70%);
        }

        /* --- 1. Topbar --- */
        .topbar {
            height: 60px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 24px;
            border-bottom: 1px solid rgba(255,255,255,0.05);
            flex-shrink: 0;
            z-index: 10;
        }

        .top-left {
            display: flex;
            align-items: center;
            gap: 16px;
        }

        .logo {
            font-weight: 800;
            font-size: 18px;
            letter-spacing: -0.5px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .logo svg {
            width: 24px;
            height: 24px;
            fill: white;
        }

        .subscribe-pill {
            background: #2a2a32;
            color: #ddd;
            padding: 6px 16px;
            border-radius: 20px;
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            transition: background 0.2s;
        }
        .subscribe-pill:hover { background: #35353d; }

        .top-right {
            display: flex;
            align-items: center;
            gap: 24px;
            font-size: 14px;
            color: #ccc;
        }

        .nav-item {
            display: flex;
            align-items: center;
            gap: 6px;
            cursor: pointer;
        }

        .nav-item.highlight { color: #fff; }
        .badge-icon {
            width: 16px; 
            height: 16px; 
            background: #ff5722; 
            border-radius: 50%; 
            display: inline-block;
            position: relative;
        }
        /* Simple dot for badge */
        .badge-dot::after {
            content: '';
            position: absolute;
            top: 2px; right: 2px;
            width: 4px; height: 4px;
            background: white;
            border-radius: 50%;
        }

        .divider-v {
            width: 1px;
            height: 16px;
            background: rgba(255,255,255,0.2);
        }

        /* --- 2. Subnav --- */
        .subnav-container {
            display: flex;
            justify-content: center;
            padding-top: 20px;
            flex-shrink: 0;
        }

        .subnav-pill {
            background: rgba(255,255,255,0.08);
            padding: 6px 12px;
            border-radius: 20px;
            display: flex;
            gap: 4px;
            align-items: center;
        }

        .subnav-item {
            padding: 6px 16px;
            border-radius: 16px;
            font-size: 13px;
            color: var(--text-secondary);
            cursor: pointer;
            transition: all 0.2s;
        }
        .subnav-item.active {
            background: rgba(255,255,255,0.15);
            color: white;
            font-weight: 500;
        }
        .subnav-item:hover:not(.active) { color: white; }

        /* --- 3. Hero Section --- */
        .hero-section {
            text-align: center;
            margin-top: 30px;
            flex-shrink: 0;
        }

        h1.wordmark {
            font-size: 80px;
            font-weight: 700;
            letter-spacing: -2px;
            margin-bottom: 8px;
            line-height: 1;
        }

        .subtitle-row {
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 8px;
            font-size: 13px;
            color: #ccc;
            margin-bottom: 8px;
        }
        .status-dot {
            width: 6px; height: 6px; background: #ef4444; border-radius: 50%; display: inline-block;}

        .quote-text {
            font-size: 13px;
            color: #888;
            max-width: 400px;
            margin: 0 auto;
            line-height: 1.5;
        }

        /* --- 4. Input Card Cluster --- */
        .workspace-area {
            flex-grow: 1;
            display: flex;
            justify-content: center;
            align-items: flex-start; /* Align to top of available space roughly */
            padding-top: 20px;
            position: relative;
        }

        .card-cluster {
            display: flex;
            gap: 10px;
            align-items: center;
            height: 280px; /* Fixed height for the card area */
        }

        /* Left Mode Rail */
        .mode-rail {
            display: flex;
            flex-direction: column;
            gap: 12px;
            padding: 12px 8px;
            background: rgba(255,255,255,0.03);
            border-radius: 12px;
            height: 100%;
            justify-content: center;
        }

        .mode-btn {
            width: 44px;
            height: 44px;
            border-radius: 8px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            color: #888;
            font-size: 9px;
            gap: 2px;
            transition: 0.2s;
            position: relative;
        }
        .mode-btn svg { width: 18px; height: 18px; fill: currentColor; }
        .mode-btn.active {
            background: rgba(255,255,255,0.1);
            color: white;
        }
        .mode-btn:hover:not(.active) { color: #bbb; background: rgba(255,255,255,0.05); }

        /* Main Card */
        .main-card {
            width: 260px;
            height: 100%;
            background: #222228; /* Slightly lighter than bg */
            border-radius: 16px;
            border: 1px solid rgba(255,255,255,0.08);
            display: flex;
            flex-direction: column;
            position: relative;
            box-shadow: 0 10px 30px rgba(0,0,0,0.3);
        }

        .card-header {
            padding: 16px;
            display: flex;
            align-items: center;
            gap: 8px;
            font-weight: 600;
            font-size: 14px;
        }
        .card-header svg { width: 16px; height: 16px; }

        .upload-zone {
            flex-grow: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 16px;
            cursor: pointer;
        }
        .plus-icon {
            width: 48px; height: 48px;
            border: 2px solid rgba(255,255,255,0.3);
            border-radius: 50%;
            display: flex; align-items: center; justify-content: center;
            font-size: 24px;
            color: white;
        }
        .text-to-img-link {
            font-size: 13px;
            color: #d8b4fe; /* Light purple */
            text-decoration: none;
        }

        /* Right Tools Rail */
        .tools-rail {
            display: flex;
            flex-direction: column;
            gap: 10px;
            padding: 4px;
        }
        .tool-icon {
            width: 36px; height: 36px;
            border-radius: 8px;
            background: rgba(255,255,255,0.05);
            display: flex; align-items: center; justify-content: center;
            color: #aaa;
            cursor: pointer;
            position: relative;
        }
        .tool-icon:hover { background: rgba(255,255,255,0.1); color: white; }
        .tool-icon svg { width: 18px; height: 18px; fill: currentColor; }
        .notif-badge {
            position: absolute; top: -2px; right: -2px;
            width: 8px; height: 8px; background: #ef4444; border-radius: 50%;
            border: 2px solid #222228;
        }

        /* --- 5. Generate Capsule & Surroundings --- */
        .generate-row {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 16px;
            margin-top: 24px;
            flex-shrink: 0;
        }

        .lock-btn {
            width: 44px; height: 44px;
            border-radius: 12px;
            background: rgba(255,255,255,0.05);
            border: 1px solid rgba(255,255,255,0.1);
            display: flex; align-items: center; justify-content: center;
            color: #888;
            cursor: pointer;
        }
        .lock-btn svg { width: 20px; fill: currentColor; }

        .generate-btn {
            background: linear-gradient(180deg, #4a3b5c 0%, #2d2238 100%);
            border: 1px solid rgba(255,255,255,0.15);
            color: white;
            padding: 0 48px;
            height: 56px;
            border-radius: 28px;
            font-size: 15px;
            font-weight: 600;
            letter-spacing: 1px;
            cursor: pointer;
            box-shadow: 0 4px 20px rgba(109, 40, 217, 0.2);
            transition: transform 0.1s;
        }
        .generate-btn:hover { transform: scale(1.02); }
        .generate-btn:active { transform: scale(0.98); }

        .gen-meta {
            display: flex;
            align-items: center;
            gap: 12px;
            color: #888;
            font-size: 13px;
        }
        .chip-mini {
            background: rgba(255,255,255,0.1);
            padding: 4px 10px;
            border-radius: 6px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        /* --- 6. Controls Row --- */
        .controls-row {
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 24px;
            margin-top: 20px;
            padding-bottom: 20px;
            flex-shrink: 0;
            font-size: 13px;
            color: #888;
        }

        .control-group {
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .control-label { color: #666; font-size: 11px; text-transform: uppercase; letter-spacing: 0.5px;}

        .pill-select {
            background: rgba(255,255,255,0.06);
            border: 1px solid rgba(255,255,255,0.1);
            padding: 6px 12px;
            border-radius: 6px;
            color: #ccc;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 6px;
        }
        .pill-select:hover { background: rgba(255,255,255,0.1); }

        .agentic-mode-box {
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .agentic-text { color: #fff; font-weight: 500; }
        .agentic-sub { font-size: 10px; color: #666; max-width: 120px; line-height: 1.2; }

        /* --- 7. Asset Header --- */
        .asset-header {
            padding: 0 40px 20px 40px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-shrink: 0;
        }
        .asset-titles { display: flex; align-items: baseline; gap: 16px; }
        .asset-title { font-size: 24px; font-weight: 700; }
        .asset-subtitle { font-size: 24px; font-weight: 700; color: #555; }

        .featured-chip {
            border: 1px solid #555;
            color: #aaa;
            padding: 6px 16px;
            border-radius: 20px;
            font-size: 12px;
            margin-top: 8px;
            display: inline-block;
        }

        .asset-actions { display: flex; gap: 10px; }
        .icon-btn {
            width: 36px; height: 36px;
            border-radius: 50%; /* Circle in img 2 looks slightly oval or circle */
            background: rgba(255,255,255,0.05);
            display: flex; align-items: center; justify-content: center;
            color: #aaa;
            border: none;
        }
        .filter-btn {
            background: rgba(255,255,255,0.05);
            border: 1px solid rgba(255,255,255,0.1);
            color: #ccc;
            padding: 0 16px;
            border-radius: 20px;
            font-size: 13px;
            display: flex; align-items: center; gap: 8px;
        }


        /* --- 8. Cookie Card --- */
        .cookie-card {
            position: fixed;
            bottom: 24px;
            right: 24px;
            width: 380px;
            background: #f3f4f6;
            color: #111;
            border-radius: 12px;
            padding: 20px;
            box-shadow: 0 10px 25px rgba(0,0,0,0.5);
            z-index: 100;
            display: flex;
            flex-direction: column;
            gap: 12px;
        }
        .cookie-title { font-weight: 700; font-size: 15px; text-align: center; }
        .cookie-desc { font-size: 12px; color: #555; line-height: 1.4; text-align: center; }
        .cookie-buttons { display: flex; gap: 10px; }
        .btn-cookie {
            flex: 1;
            padding: 10px;
            border-radius: 8px;
            font-size: 13px;
            font-weight: 600;
            cursor: pointer;
            border: none;
            text-align: center;
        }
        .btn-accept { background: #4f46e5; color: white; }
        .btn-pref { background: white; color: #333; border: 1px solid #ddd; }

        /* Floating 'N' button bottom left (Image 2 artifact) */
        .float-n {
            position: fixed;
            bottom: 24px;
            left: 24px;
            width: 32px; height: 32px;
            background: #000;
            color: #fff;
            border-radius: 50%;
            display: flex; align-items: center; justify-content: center;
            font-weight: bold;
            font-size: 14px;
            z-index: 90;
        }

    </style>
</head>
